# 45 vodka brands: (slug, name, url, verified fact, observation 1, observation 2, slide notes [(text, fx, fy)])
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
("smirnoff","Smirnoff","https://www.smirnoff.com/","Pyotr Smirnov built his vodka business in Moscow in the 1860s, and the brand later grew into the world's best-selling vodka.","A red banner sits across a silver crest, like an imperial seal.","The heraldic shape is a reminder of the brand's 19th-century Russian roots."),
("absolut","Absolut","https://www.absolut.com/","Absolut was launched in 1979 in Åhus, Sweden, building on a vodka first sold by Lars Olsson Smith in 1879.","Heavy blue capitals are paired with a handwritten \"Country of Sweden\" in the middle.","The logo is printed straight onto the famous bottle, which became the star of its advertising."),
("grey-goose","Grey Goose","https://www.greygoose.com/","Sidney Frank created Grey Goose in 1997, and it is distilled in the Cognac region of France.","A goose in flight sits above thin, spaced capitals.","The quiet serif and pale blue feel French and premium rather than loud."),
("ketel-one","Ketel One","https://www.ketelone.com/","The Nolet family has distilled in Schiedam, the Netherlands, since 1691, and Ketel One is named after their copper pot still.","A large blackletter K gives the name an old Dutch character.","Black, white and a touch of red keep the logo crisp on the bottle."),
("belvedere","Belvedere","https://www.belvederevodka.com/","Belvedere was launched in 1993 in Żyrardów, Poland, and is named after the Belweder Palace in Warsaw.","Tall serif capitals feel classical, like the palace on the bottle.","Widely spaced blue VODKA underneath adds calm and balance."),
("stolichnaya","Stolichnaya","https://stoli.com/","Stolichnaya means \"of the capital\", and in 2022 the brand shortened its name to Stoli.","Very widely spaced capitals make the short name feel modern and minimal.","Dropping the long Russian name was a branding decision as much as a design one."),
("skyy","Skyy","https://www.skyyvodka.com/","Maurice Kanbar launched Skyy in San Francisco in 1992.","Bold, tight capitals in cobalt blue match the brand's famous blue bottle.","The double Y makes the short name more memorable."),
("ciroc","Cîroc","https://www.ciroc.com/","Cîroc was launched in 2003 and is made from French grapes rather than grain.","The circumflex over the I is a small French detail that makes the name distinctive.","Thin, spaced capitals feel like a luxury fashion brand."),
("finlandia","Finlandia","https://www.finlandia.com/","Finlandia was launched in 1970 and is made from Finnish barley and glacial spring water.","Condensed capitals stack the name over a spaced VODKA line.","A small emblem above the name adds a touch of nature and heritage."),
("beluga","Beluga","https://belugavodka.com/","Beluga is made at the Mariinsk distillery in Siberia and was launched in 2002.","A sturgeon fish sits above the name, a direct link to the beluga sturgeon.","Heavy capitals and \"The Noble Vodka\" make the brand feel premium and Russian."),
("zubrowka","Żubrówka","https://zubrowka.com/","Żubrówka is a Polish vodka flavoured with bison grass, and every bottle has a blade of grass inside.","A bison stands under the name, the animal that grazes on the grass in the Białowieża Forest.","Arched, hand-drawn capitals feel folk-like and traditional."),
("chopin","Chopin","https://www.chopinvodka.com/","Chopin is a Polish potato vodka launched in 1993 and named after the composer Frédéric Chopin.","The flowing script looks like a composer's signature.","Small VODKA tucked into the script keeps the focus on the name."),
("wyborowa","Wyborowa","https://wyborowa.pl/","Wyborowa is one of Poland's oldest vodka brands, and its name means \"exquisite\" or \"choice\" in Polish.","Tall, heavy condensed capitals feel strong and confident.","The simple black wordmark works on clear glass and labels."),
("nemiroff","Nemiroff","https://nemiroff.vodka/","Nemiroff is a Ukrainian brand from the town of Nemyriv, with roots going back to 1872.","A small round emblem sits above the name with the founding year.","Slanted serif capitals give the wordmark a lively, classic feel."),
("sobieski","Sobieski","https://www.sobieski.com/","Sobieski is a Polish vodka named after King John III Sobieski.","A royal crown above the name links the brand to the king.","Serif capitals in a dark blue band look like a royal seal."),
("khortytsa","Khortytsa","https://khortytsa.com/","Khortytsa is a Ukrainian vodka named after Khortytsia, an island on the Dnipro river.","The name is written in Cyrillic, which keeps the brand rooted in Ukraine.","Gold lettering and a round emblem make it feel premium."),
("green-mark","Green Mark","https://www.zelenaya-marka.ru/","Green Mark launched in Russia in the early 2000s and became one of the country's best-selling vodkas.","A large check mark crosses the name like a stamp of approval.","Serif lettering keeps the brand feeling traditional."),
("pravda","Pravda","https://www.pravdavodka.com/","Pravda is a Polish vodka whose name means \"truth\".","The italic serif name sits on a yellow underline.","The single colour accent makes a simple wordmark easy to spot."),
("titos","Tito's","https://www.titosvodka.com/","Bert \"Tito\" Beveridge started Tito's in Austin, Texas, in 1997, at the first legal distillery in the state.","Hand-drawn italic letters look like an old Texas sign.","The founder's nickname is the brand, which makes it feel personal."),
("svedka","Svedka","https://svedka.com/","Svedka was launched in 1998 as a Swedish-made vodka sold mainly in the United States.","The A is drawn as an upside-down V, a small futuristic detail.","The glowing blue look matches the brand's sci-fi advertising."),
("deep-eddy","Deep Eddy","https://deepeddyvodka.com/","Deep Eddy was founded in Austin, Texas, in 2010 and is named after Deep Eddy Pool, the oldest swimming pool in Texas.","A diver jumps between the two words.","The round badge looks like a vintage pool sign."),
("pinnacle","Pinnacle","https://www.pinnaclevodka.com/","Pinnacle vodka is made in France and is known for its many flavours.","A mountain peak sits above the name, a direct picture of \"pinnacle\".","White serif capitals on a deep blue box look like a classic label."),
("hangar-1","Hangar 1","https://www.hangarone.com/","Hangar 1 started in 2002 in a former Navy airplane hangar in Alameda, California.","A big script with a large number 1 feels like vintage aircraft lettering.","\"Hand-crafted in California\" underneath tells the craft story."),
("wheatley","Wheatley","https://www.wheatleyvodka.com/","Wheatley was created at Buffalo Trace in Kentucky and is named after master distiller Harlen Wheatley.","Stacked western capitals look like an old frontier poster.","\"American Vodka\" in the middle makes the origin clear."),
("western-son","Western Son","https://www.westernsondistillery.com/","Western Son is a Texas distillery known for its flavoured vodkas.","A bird in flight sits next to tall condensed capitals.","The western name and type give the brand a frontier feel."),
("uv","UV","https://uvvodka.com/","UV is made by Phillips Distilling in Minnesota and is known for its bright flavoured vodkas.","Two huge capitals make the shortest possible name.","Widely spaced VODKA underneath balances the heavy letters."),
("three-olives","Three Olives","https://www.threeolives.com/","Three Olives is made in England and is known for its long range of flavoured vodkas.","Playful brush lettering makes the brand feel fun.","The name hints at a martini with three olives."),
("crystal-head","Crystal Head","https://www.crystalheadvodka.com/","Actor Dan Aykroyd and artist John Alexander launched Crystal Head in 2008 in a skull-shaped bottle.","Rough, typewriter-like lettering feels mysterious.","The bottle is the real logo, and the wordmark stays simple."),
("absolut-elyx","Absolut Elyx","https://www.absolutelyx.com/","Absolut Elyx was launched in 2013 as a single estate vodka made in a 1920s copper still.","A copper colour links the logo to the copper still.","Condensed type and a small emblem feel like a vintage cocktail bar."),
("van-gogh","Van Gogh","https://www.vangoghvodka.com/","Van Gogh vodka is made in the Netherlands and named after the Dutch painter.","Bold capitals with a thin line feel modern and clean.","\"The Art of Vodka\" links the drink to the painter."),
("effen","Effen","https://www.effenvodka.com/","Effen is a Dutch vodka launched in 2002, and its name means \"smooth\" or \"even\" in Dutch.","The letters are built from thin horizontal lines, like a design experiment.","Very wide spacing makes the short word feel calm and premium."),
("elit","Elit","https://www.elitvodka.com/","Elit is the luxury vodka from Stoli, launched in 2003 and filtered at freezing temperatures.","A tall, narrow mark looks like a drop of ice.","The lowercase name feels modern and light."),
("kauffman","Kauffman","https://www.kauffman-vodka.com/","Kauffman is a luxury Russian vodka known for being sold as a vintage, with a year on every bottle.","The oval badge on black looks like a jewellery stamp.","Small serif type inside the oval feels exclusive."),
("black-cow","Black Cow","https://www.blackcow.co.uk/","Dorset dairy farmer Jason Barber created Black Cow in 2012, a vodka made from the whey of cows' milk.","A cow silhouette sits above clean spaced capitals.","The animal is a direct and funny picture of the milk vodka."),
("st-george","St. George","https://stgeorgespirits.com/","St. George Spirits was founded in Alameda, California, in 1982 and is one of America's first craft distilleries.","Simple capitals keep the name plain and honest.","The quiet logo lets the bottles and spirits do the talking."),
("hanson-of-sonoma","Hanson of Sonoma","https://hansonofsonoma.com/","Hanson of Sonoma is a family distillery in Sonoma, California, that makes vodka from organic grapes.","Bold capitals stack over a small \"Sonoma\" line.","The wine-country name links the vodka to the grapes it is made from."),
("reyka","Reyka","https://www.reykavodka.com/","Reyka is made in Borgarnes, Iceland, using Icelandic water filtered through lava rock.","Widely spaced capitals feel cold, clean and Nordic.","The simple wordmark matches the brand's focus on pure water."),
("danzka","Danzka","https://www.danzka.com/","Danzka is a Danish vodka known for its aluminium bottle.","Bold, spaced capitals inside a black box look like a stamp.","The metal bottle and the boxed logo feel industrial and modern."),
("koskenkorva","Koskenkorva","https://www.koskenkorva.com/","Koskenkorva comes from the village of Koskenkorva in Finland, where its distillery opened in 1938.","Heavy condensed capitals stack the long Finnish name over VODKA.","The bold type makes the brand feel strong and simple."),
("eristoff","Eristoff","https://www.eristoff.com/","Eristoff dates its recipe to 1806 and the Georgian prince Eristavi.","Tall, heavy capitals feel strong and Eastern European.","\"From the land of the wolf\" adds a story to a simple wordmark."),
("explorer","Explorer","https://www.explorervodka.com/","Explorer is a Swedish vodka brand that uses a Viking ship as its symbol.","A Viking ship sits inside a pale blue square like a stamp.","The small type below keeps the ship as the main symbol."),
("ursus","Ursus","https://www.ursusvodka.com/","Ursus is a Dutch vodka, and its name means \"bear\" in Latin.","Heavy capitals between two thick lines look like a label band.","The simple black mark is easy to recognise on a bar shelf."),
("iceberg","Iceberg","https://www.icebergvodka.com/","Iceberg vodka is made in Canada with water from icebergs off Newfoundland.","Bold condensed capitals feel cold and strong.","A small maple leaf above the name shows it is Canadian."),
("42-below","42 Below","https://www.42below.com/","42 Below was founded in Wellington, New Zealand, in 1999 and is named after the city's latitude.","The number 42 makes the name easy to remember.","A vertical \"This is\" adds a playful, cheeky tone."),
("blue-ice","Blue Ice","https://www.blueicevodka.com/","Blue Ice is an American vodka made from Idaho potatoes.","Classic small capitals feel traditional and simple.","The name and logo suggest something cold and clean."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 45
